//! Weir rules for German.
//!
//! Generated by `build.rs` from the `.weir` files in this directory: the
//! `lint_group()` below and one test per rule, running its own `test` and
//! `allows` lines. Adding a rule file is the whole edit.

use harper_core::Token;
use harper_core::expr::Expr;
use harper_core::linting::{ExprLinter, Lint};

/// The priority every German Weir rule reports with.
///
/// A Weir rule names one specific mistake and its fix, so where it overlaps a
/// general rule it is the better report. The core gives every Weir lint 31, and
/// a lint group keeps the lowest number where reports overlap, so the general
/// rules won: *garkein* drew the spell checker's *Wardeine*, and *garnicht* the
/// noun capitalization's *Garnicht*, instead of *gar kein* and *gar nicht*.
/// 18 is below the spell checker (20) and the noun capitalization (25), and
/// above the spacing rule (15), whose one-character spans a Weir rule never
/// wants to hide.
pub const WEIR_PRIORITY: u8 = 18;

/// A Weir rule reporting with [`WEIR_PRIORITY`] instead of the core's 31.
pub struct Prioritized<L>(pub L);

impl<L: ExprLinter> ExprLinter for Prioritized<L> {
    type Unit = L::Unit;

    fn expr(&self) -> &dyn Expr {
        self.0.expr()
    }

    fn match_to_lint_with_context(
        &self,
        matched_tokens: &[Token],
        source: &[char],
        context: Option<(&[Token], &[Token])>,
    ) -> Option<Lint> {
        self.0
            .match_to_lint_with_context(matched_tokens, source, context)
            .map(|lint| Lint {
                priority: WEIR_PRIORITY,
                ..lint
            })
    }

    fn description(&self) -> &str {
        self.0.description()
    }
}

include!(env!("GERMAN_WEIR_RULE_LIST"));
